import os,re,json
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
def rot90(g): return [list(r) for r in zip(*g[::-1])]
def flip(g): return [r[::-1] for r in g]
import numpy as np
a=np.array(inp); o=np.array(out)
transforms={'id':a,'r90':np.rot90(a,1),'r180':np.rot90(a,2),'r270':np.rot90(a,3),'fh':np.fliplr(a),'fv':np.flipud(a),'d1':a.T,'d2':np.fliplr(np.rot90(a,2))}
for i in range(3):
    for j in range(3):
        b=o[i*3:(i+1)*3, j*3:(j+1)*3]
        for k,v in transforms.items():
            if np.array_equal(b,v): print(i,j,k); break
        else: print(i,j,'NONE',b.tolist())
